package com.cefalo.angulos;

import android.app.Activity;
import android.content.Intent;
import android.graphics.BitmapFactory;
import android.os.Bundle;
import android.util.Base64;
import android.widget.ImageView;
import android.widget.TextView;

public class MainActivity extends Activity {
    private static final String LOGO_B64 = "";
    private static final String MASCOT_B64 = "";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        TextView btnSteiner = findViewById(R.id.btnSteiner);
        TextView btnVertebral = findViewById(R.id.btnVertebral);
        ImageView imgLogo = findViewById(R.id.imgLogo);
        ImageView imgMascot = findViewById(R.id.imgMascot);

        byte[] logoBytes = Base64.decode(LOGO_B64, Base64.DEFAULT);
        byte[] mascotBytes = Base64.decode(MASCOT_B64, Base64.DEFAULT);
        imgLogo.setImageBitmap(BitmapFactory.decodeByteArray(logoBytes, 0, logoBytes.length));
        imgMascot.setImageBitmap(BitmapFactory.decodeByteArray(mascotBytes, 0, mascotBytes.length));

        btnSteiner.setOnClickListener(v -> openAnalysis("STEINER"));
        btnVertebral.setOnClickListener(v -> openAnalysis("VERTEBRAL"));
    }

    private void openAnalysis(String mode) {
        Intent intent = new Intent(this, AnalysisActivity.class);
        intent.putExtra("MODE", mode);
        startActivity(intent);
    }
}
